SELECT f.page_id,f.slot,r.title,f.written,e.user author,v.born_rev,CONCAT('https://fi.wikipedia.org/?oldid=',v.born_rev) oldid,LEFT(t.text,600) excerpt,f.referenced previously_referenced FROM facts f JOIN first_versions v USING(page_id,slot) JOIN wtt.passage_text t ON t.hash=f.hash JOIN wtt.revision r ON r.page_id=f.page_id LEFT JOIN wtt.edit e ON e.rev_id=v.born_rev WHERE NOT f.has_ref ORDER BY written,f.page_id,f.slot LIMIT 25;
